```python
import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    if not isinstance(script_path, str):
        raise TypeError("script_path must be a string")
    if script_path == "" or not os.path.exists(script_path):
        raise OSError("script_path does not exist")

    proc = subprocess.Popen(["bash", script_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    start = time.time()

    try:
        p = psutil.Process(proc.pid)
    except psutil.NoSuchProcess:
        return {"CPU Usage": 0.0, "Memory Usage": 0}

    total_cpu = 0.0
    total_mem = 0
    try:
        p.cpu_percent(None)
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        return {"CPU Usage": 0.0, "Memory Usage": 0}

    try:
        prev_rss = p.memory_info().rss
    except (psutil.NoSuchProcess, psutil.ZombieProcess):
        prev_rss = 0

    interval = 0.1
    while True:
        if time.time() - start >= timeout:
            break

        if proc.poll() is not None:
            break

        try:
            if p.status() == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

        time.sleep(interval)

        try:
            total_cpu += p.cpu_percent(None)
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

        try:
            rss = p.memory_info().rss
            delta = rss - prev_rss
            if delta > 0:
                total_mem += delta
            prev_rss = rss
        except (psutil.NoSuchProcess, psutil.ZombieProcess):
            break

    if proc.poll() is None:
        try:
            proc.terminate()
            proc.wait(timeout=1)
        except Exception:
            try:
                proc.kill()
                proc.wait(timeout=1)
            except Exception:
                pass

    return {"CPU Usage": float(total_cpu), "Memory Usage": int(total_mem)}
