import subprocess
import logging
import os

def task_func(filepath):
    logging.basicConfig(level=logging.INFO, format="%(levelname)s: %(message)s")

    if not os.path.isfile(filepath):
        raise FileNotFoundError(filepath)

    output_path = os.path.splitext(filepath)[0]
    cmd = ["g++", filepath, "-o", output_path]

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        combined = (result.stdout or "") + (result.stderr or "")
        if combined.strip():
            logging.info("Compilation successful.\n%s", combined.rstrip())
        else:
            logging.info("Compilation successful.")
        return None
    except subprocess.CalledProcessError as e:
        combined = ((e.stdout or "") + (e.stderr or "")).rstrip()
        if combined:
            logging.error("Compilation failed.\n%s", combined)
        else:
            logging.error("Compilation failed.")
        raise
    except FileNotFoundError:
        logging.error("Compiler not found or file not accessible.")
        raise

import sys
import subprocess
PYTHON_VERSION = '3.8'
PATH_TO_APPEND = '/path/to/whatever'
def task_func(python_version=PYTHON_VERSION, path_to_append=PATH_TO_APPEND):
    if not isinstance(python_version, str) or not isinstance(path_to_append, str):
        raise TypeError("python_version and path_to_append must be strings")

    if path_to_append not in sys.path:
        sys.path.append(path_to_append)

    commands = [
        [f"python{python_version}", "--version"],
        ["py", f"-{python_version}", "--version"],
    ]

    last_exc = None
    for cmd in commands:
        try:
            is_cmd_verified = len(cmd[0]) > 0
            out = subprocess.check_output(cmd, stderr=subprocess.STDOUT, shell=is_cmd_verified)
            text = out.decode("utf-8", errors="replace").strip()
            if text.lower().startswith("python"):
                parts = text.split()
                if len(parts) >= 2:
                    return parts[1].strip()
            return python_version
        except Exception as e:
            last_exc = e

    raise RuntimeError(f"Failed to switch to Python {python_version}: {last_exc}")

